      askCopyMdBtn.setAttribute('aria-label', ok ? 'Ask thread copied as Markdown' : 'Copy failed — try again');
      if(typeof showAnalyzeToast === 'function') showAnalyzeToast(ok ? '📋 Markdown copied' : '⚠ Couldn’t copy');
